      knownAssetsSubtotal,
      knownLiabilitiesSubtotal,
      knownNetWorthSubtotal,
      fxComplete,
      pricesComplete,
      valuationComplete: fxComplete && pricesComplete,
      missingRatePairs: [...pairs].sort(),
      unpricedSecurityIds: [...unpriced.keys()].sort(),
      unpricedSymbols: [...unpriced.values()].sort(),
    };
  }

